registryContract = w3.eth.contract(address=REGISTRY, abi=REGISTRY_ABI)

def getPrefixedMess(message: str) -> bytes:
    msg_bytes = message.encode("utf-8")
    prefix = f"\x19Ethereum Signed Message:\n{len(msg_bytes)}".encode("utf-8")
    return keccak(prefix + msg_bytes)

def prepareMess(productId: int, manufacturerAddress: str) -> dict:
    manufacturer = to_checksum_address(manufacturerAddress)
    info = registryContract.functions.getProductInfo(int(productId), manufacturer).call()

    message = (f"productId: {int(productId)}\n"
        f"manufacturerAddress: {manufacturer}\n"
        f"name: {info[1]}\n"
        f"serialNumber: {info[2]}")

    return message

def normalizeSig(sig_hex: str) -> bytes:
    s = sig_hex[2:] if sig_hex.startswith("0x") else sig_hex
    raw = bytes.fromhex(s)
    if len(raw) != 65:
        raise ValueError(f"Expected 65-byte signature, got {len(raw)}")
    v = raw[64]
    if v >= 27:
        v -= 27
    return raw[:64] + bytes([v])

def recoverSigner(message: str, sig_hex: str):
    address = Account.recover_message(encode_defunct(text=message), signature=sig_hex)
    return (to_checksum_address(address))

def recoverPublicKey(messagePrefixed: bytes, sig_hex: str):
    sig_bytes = normalizeSig(sig_hex)
    pubkey = keys.Signature(sig_bytes).recover_public_key_from_msg_hash(messagePrefixed)
    return pubkey.to_compressed_bytes()


def makeQR(productId: int, manufacturerAddress: str, signatureHex: str) -> dict:
    
    message = prepareMess(productId, manufacturerAddress)
    messageWithPrefix = getPrefixedMess(message)

    signer = recoverSigner(message, signatureHex)
    publicKeyCompressed = recoverPublicKey(messageWithPrefix, signatureHex)

    ind1, ind2 = registryContract.functions.checkManufacturer(to_checksum_address(manufacturerAddress), to_checksum_address(signer)).call()

    if ind1 != True and ind2 != "employee":
        raise ValueError( f"User does not have permission to sign QR for this product.")

    sigBytes = normalizeSig(signatureHex)
    if sigBytes[64] < 27:
        sigBytes = sigBytes[:64] + bytes([sigBytes[64] + 27])
    
    qr = generateDualQR(productId, manufacturerAddress, sigBytes)
    
    return {"qrPng": qr, "publicKeyCompressed": publicKeyCompressed.hex()}
